const $=s=>document.querySelector(s), {Game,names}=Snack;let saved={unlocked:1,stars:{},volume:.55};try{Object.assign(saved,JSON.parse(localStorage.getItem('snack-trip-v1')||'{}'));}catch{}let game,level=1,busy=false,selected=-1,tool=null,counts={},audio,gesture,epoch=0,ended=false,lastFocus=null;
function persist(){try{localStorage.setItem('snack-trip-v1',JSON.stringify(saved));}catch{}}
function sound(kind,chain=1){try{audio ||=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(!saved.volume)return;let seq={tap:[420],swap:[390,520],bad:[220,170],clear:[523,659,784],ice:[1100,1450],tool:[250,500,1000],win:[523,659,784,1047],lose:[440,349,262]}[kind]||[500];seq.forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.07;o.type=kind==='ice'?'triangle':'sine';o.frequency.setValueAtTime(f*(kind==='clear'?Math.min(1.7,1+chain*.07):1),t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(saved.volume*.13,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.22);});}catch{}}
const wait=ms=>new Promise(r=>setTimeout(r,ms));function pos(v){return `${v%3*50}% ${v<3?0:100}%`;}
function draw(anim=[]){$('#board').innerHTML=game.b.map((v,i)=>`<button class="cell ${!game.cfg.mask[i]?'void':''} ${game.boxes[i]?'box':''} ${game.ice[i]?'ice':''} ${game.jelly[i]?'jelly':''} ${selected===i?'selected':''} ${anim.includes(i)?'fall':''}" data-i="${i}" aria-label="第${(i/7|0)+1}排第${i%7+1}格 ${game.boxes[i]?'木箱':names[v]||'空格'}${game.ice[i]?' 冰層':''}${game.jelly[i]?' 果醬':''}" ${!game.cfg.mask[i]?'disabled tabindex="-1"':''}>${v>=0&&!game.boxes[i]?`<span class="food" style="background-position:${pos(v)}"></span>`:''}${game.ice[i]+game.jelly[i]+game.boxes[i]>1?`<span class="layer">${game.ice[i]+game.jelly[i]+game.boxes[i]}</span>`:''}</button>`).join('');hud();}
function hud(){
$('#moves').textContent=game.moves;$('#score').textContent=`✦ ${game.score.toLocaleString()}`;$('#levelLabel').textContent=`第 ${level} 關`;
const sum=a=>a.reduce((x,y)=>x+y,0), ice=sum(game.ice),box=sum(game.boxes),jelly=sum(game.jelly);
let parts=[];if(game.cfg.target)parts.push(`<span><i class="food-mini" style="background-position:${pos(game.cfg.food)}"></i> ${Math.min(game.got,game.cfg.target)}/${game.cfg.target}</span>`);
if(game.cfg.scoreTarget)parts.push(`<span>✦ ${Math.min(game.score,game.cfg.scoreTarget)}/${game.cfg.scoreTarget}</span>`);
if(sum(game.cfg.ice))parts.push(`<span title="剩餘冰層">❄ ${ice}</span>`);if(sum(game.cfg.boxes))parts.push(`<span title="剩餘木箱層數">▧ ${box}</span>`);if(sum(game.cfg.jelly))parts.push(`<span title="剩餘果醬層數">▨ ${jelly}</span>`);$('#goals').innerHTML=parts.join('');
let ratios=[];if(game.cfg.target)ratios.push(Math.min(1,game.got/game.cfg.target));if(game.cfg.scoreTarget)ratios.push(Math.min(1,game.score/game.cfg.scoreTarget));let obstacles=sum(game.cfg.ice)+sum(game.cfg.boxes)+sum(game.cfg.jelly);if(obstacles)ratios.push(1-(ice+box+jelly)/obstacles);$('#progress').style.width=`${100*ratios.reduce((a,b)=>a+b,0)/ratios.length}%`;
for(let k of Object.keys(counts)){$(`#${k}Count`).textContent=counts[k];$(`[data-tool=${k}]`).classList.toggle('armed',tool===k);$(`[data-tool=${k}]`).disabled=counts[k]<=0||ended;}
}

function start(l){epoch++;$('.board-wrap').querySelectorAll('.cascade-stage').forEach(e=>e.remove());$('#fx').classList.remove('show');$('#fx').textContent='';ended=false;gesture=null;level=l;game=new Game(l);counts={hammer:3,row:2,shuffle:2};busy=false;selected=-1;tool=null;$('#overlay').hidden=true;$('.app').inert=false;$('.app').classList.toggle('tall-board',game.cfg.rows>7);$('#chapter').textContent=`${String(Math.ceil(l/10)).padStart(2,'0')} / ${['草莓野餐','布丁小徑','森林午茶','葡萄果園','糖果海灣','甜甜圈街','冰霜廚房','木箱市集','星光餐桌','終點盛宴'][Math.ceil(l/10)-1]}`;$('#instruction').textContent='滑一下交換食物 · 連成 3 個就能消除';$('#combo').textContent=game.cfg.name+' · '+game.cfg.difficulty;$('#instruction').textContent={order:'收集訂單 · 清完障礙',clear:'清除所有障礙 · 滑動或點兩格交換',score:'達成分數 · 清完障礙',mixed:'混合任務 · 收集與清除'}[game.cfg.mode];draw();}
function flash(text){$('#fx').textContent=text;$('#fx').classList.remove('show');void $('#fx').offsetWidth;$('#fx').classList.add('show');}
function cascadeFX(chain,ids){
const wrap=$('.board-wrap'),p=SnackEffects.profile(chain,window.matchMedia('(prefers-reduced-motion: reduce)').matches);
wrap.querySelectorAll('.cascade-stage').forEach(e=>e.remove());
if(chain>1){$('#fx').dataset.tier=p.tier;flash(`${chain} 連鎖 · ${p.label}`);}
if(!p.particles)return;
const layer=document.createElement('div');layer.className=`cascade-stage tier-${p.tier}`;layer.setAttribute('aria-hidden','true');wrap.append(layer);
const rect=wrap.getBoundingClientRect(),colors=['#ebaa55','#db737c','#7eae91','#85bcd3','#b293c8','#fff5ca'];
const origins=ids.map(i=>$(`[data-i="${i}"]`)?.getBoundingClientRect()).filter(Boolean).map(r=>({x:r.x-rect.x+r.width/2,y:r.y-rect.y+r.height/2}));
for(let n=0;n<p.particles;n++){const o=origins[n%origins.length]||{x:rect.width/2,y:rect.height/2},angle=Math.random()*Math.PI*2,dist=25+Math.random()*(25+p.tier*19),dot=document.createElement('i');dot.className=p.confetti&&n%3===0?'cascade-bit ribbon':'cascade-bit';dot.style.cssText=`left:${o.x}px;top:${o.y}px;background:${colors[n%colors.length]};--dx:${Math.cos(angle)*dist}px;--dy:${Math.sin(angle)*dist}px;--spin:${(Math.random()-.5)*600}deg;--life:${p.duration}ms;--size:${3+p.tier+Math.random()*4}px`;layer.append(dot);}
for(let n=0;n<p.rings;n++){const ring=document.createElement('i');ring.className='cascade-ring';ring.style.cssText=`--delay:${n*65}ms;--ring:${colors[(n+chain)%colors.length]};--life:${p.duration}ms`;layer.append(ring);}
if(p.tier>=4){const rays=document.createElement('i');rays.className='cascade-rays';layer.prepend(rays);}
setTimeout(()=>layer.remove(),p.duration+300);
}
async function resolve(ids){let chain=0,token=epoch;while(ids.length){chain++;let frozen=ids.some(i=>game.ice[i]);ids.forEach(i=>$(`[data-i="${i}"]`)?.classList.add('pop'));sound(frozen?'ice':'clear',chain);cascadeFX(chain,ids);$('#combo').textContent=chain>1?`${chain} 連鎖 · 太美味了！`:'好吃！';await wait(240);if(epoch!==token)return;game.clear(ids);draw();await wait(80);if(epoch!==token)return;let empty=game.b.map((v,i)=>v<0&&game.active(i)?i:-1).filter(i=>i>=0);game.fall();draw(empty);await wait(280);if(epoch!==token)return;ids=game.match();}if(game.won()){busy=false;result(true);return;}if(game.moves<=0){busy=false;result(false);return;}if(!game.legal().length){flash('沒有可走步，免費重排');game.shuffle();draw(game.b.map((_,i)=>i));sound('tool');}busy=false;}
async function swap(a,b){if(busy||ended||!game.active(a)||!game.active(b)||!game.adj(a,b))return;busy=true;selected=-1;let token=epoch,elA=$(`[data-i="${a}"]`),elB=$(`[data-i="${b}"]`),ra=elA.getBoundingClientRect(),rb=elB.getBoundingClientRect();elA.style.transform=`translate(${rb.x-ra.x}px,${rb.y-ra.y}px)`;elB.style.transform=`translate(${ra.x-rb.x}px,${ra.y-rb.y}px)`;sound('swap');await wait(170);if(token!==epoch)return;game.swap(a,b);draw();let ids=game.match();if(!ids.length){sound('bad');$('#instruction').textContent='需要連成 3 個相同食物，不會扣步數';await wait(140);if(token!==epoch)return;game.swap(a,b);draw();busy=false;return;}game.moves--;hud();await resolve(ids);}
async function choose(i){if(busy||ended||!game.cfg.mask[i])return;sound('tap');if(tool){if(tool==='hammer'||tool==='row'){busy=true;counts[tool]--;let ids=tool==='hammer'?[i]:Array.from({length:7},(_,c)=>(i/7|0)*7+c).filter(j=>game.cfg.mask[j]);tool=null;selected=-1;hud();sound('tool');await resolve(ids);$('#instruction').textContent='滑一下交換食物 · 連成 3 個就能消除';}return;}if(!game.active(i))return;if(selected===i)selected=-1;else if(selected>=0&&game.adj(selected,i)){await swap(selected,i);return;}else selected=i;draw();}
$('#board').addEventListener('pointerdown',e=>{let cell=e.target.closest('[data-i]');if(!cell||busy||ended)return;gesture={i:+cell.dataset.i,x:e.clientX,y:e.clientY,id:e.pointerId};$('#board').setPointerCapture(e.pointerId);});
$('#board').addEventListener('pointerup',e=>{if(!gesture)return;let g=gesture;gesture=null;if(busy)return;let dx=e.clientX-g.x,dy=e.clientY-g.y;if(!tool&&Math.max(Math.abs(dx),Math.abs(dy))>12){let b=g.i+(Math.abs(dx)>Math.abs(dy)?(dx>0?1:-1):(dy>0?7:-7));swap(g.i,b);}else choose(g.i);});$('#board').addEventListener('pointercancel',()=>gesture=null);$('#board').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(+e.target.closest('[data-i]').dataset.i);}});
document.querySelectorAll('[data-tool]').forEach(el=>el.onclick=async()=>{if(busy)return;if(ended)return;let k=el.dataset.tool;if(!counts[k])return;sound('tap');if(k==='shuffle'){busy=true;counts[k]--;game.shuffle();draw(game.b.map((_,i)=>i));sound('tool');flash('新鮮重排！');await wait(300);busy=false;}else{tool=tool===k?null:k;selected=-1;$('#instruction').textContent=tool?`點選棋盤，${k==='hammer'?'敲掉指定的一格':'清除指定的一整排'}（不扣步數）`:'已取消道具';draw();}});
$('#hintBtn').onclick=()=>{if(busy||ended)return;sound('tap');document.querySelectorAll('.hint').forEach(e=>e.classList.remove('hint'));let m=game.legal()[0];if(m)m.forEach(i=>$(`[data-i="${i}"]`).classList.add('hint'));$('#instruction').textContent='交換閃動的兩個食物，試試看！';};
function modal(html){if($('#overlay').hidden)lastFocus=document.activeElement;$('#modal').innerHTML='<button class="modal-close" aria-label="關閉視窗" title="關閉">×</button><div class="modal-content">'+html+'</div>';$('#overlay').hidden=false;$('#modal').setAttribute('role','dialog');$('#modal').setAttribute('aria-modal','true');$('#modal').setAttribute('aria-label',$('#modal h2')?.textContent||'遊戲視窗');$('.app').inert=true;$('.modal-close').onclick=close;$('.modal-close').focus();}function close(){$('#overlay').hidden=true;$('.app').inert=false;lastFocus?.focus();}
document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){let nodes=[...$('#modal').querySelectorAll('button:not(:disabled),input')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});function result(win){ended=true;hud();$('#instruction').textContent=win?'已通關，可從關卡地圖前往下一關':'步數已用完，點選重新挑戰再試一次';sound(win?'win':'lose');let stars=win?game.moves>=10?3:game.moves>=4?2:1:0;if(win){saved.stars[level]=Math.max(saved.stars[level]||0,stars);saved.unlocked=Math.min(100,Math.max(saved.unlocked,level+1));persist();}modal(`<span class="eyebrow">LEVEL ${level} / 100</span><h2>${win?level===100?'百關盛宴，完成！':'訂單完成！':'再差一小口！'}</h2><div class="stars">${win?'★'.repeat(stars)+'☆'.repeat(3-stars):'♡'}</div><p>${win?'點心都準備好了，帶著好心情繼續旅行。':'這次步數用完了。換個順序，善用不扣步數的道具，再試一次！'}<br>本次得分 ${game.score.toLocaleString()} · 剩餘 ${game.moves} 步</p><button class="primary" id="next">${win&&level<100?'下一關 →':'再玩一次'}</button><button class="secondary" id="backMap">關卡地圖</button>`);$('#next').onclick=()=>start(win&&level<100?level+1:level);$('#backMap').onclick=map;}
function map(){if(busy)return;modal(`<span class="eyebrow">YOUR LITTLE JOURNEY</span><h2>100 個美味小日子</h2><p>已通過 ${Object.keys(saved.stars).length} 關 · 依序解鎖下一站</p><div class="mapgrid">${Array.from({length:100},(_,i)=>`<button title="${Snack.config(i+1).name} · ${Snack.config(i+1).difficulty}" data-level="${i+1}" class="${i+1===level?'current':''}" ${i+1>saved.unlocked?'disabled':''}>${i+1>saved.unlocked?'♙':i+1}<small>${saved.stars[i+1]?'★'.repeat(saved.stars[i+1]):'·'}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(e=>e.onclick=()=>start(+e.dataset.level));}
$('#mapBtn').onclick=map;$('#settingsBtn').onclick=()=>{if(busy)return;modal(`<span class="eyebrow">MAKE YOURSELF COMFORTABLE</span><h2>舒服地玩</h2><p>音效音量 <b id="volumeLabel">${Math.round(saved.volume*100)}%</b></p><input aria-label="音效音量" id="volume" type="range" min="0" max="100" value="${saved.volume*100}"><p>進度自動儲存在這台裝置的瀏覽器。音效會在第一次點擊後啟動。</p>`);$('#volume').oninput=e=>{saved.volume=+e.target.value/100;$('#volumeLabel').textContent=e.target.value+'%';persist();sound('tap');};};
function help(){if(busy)return;modal(`<span class="eyebrow">A RECIPE FOR FUN</span><h2>滑一下，就上手。</h2><p>① 滑動食物，與上下左右相鄰食物交換；也可以依序點選兩格。<br>② 三個以上相同食物連成直線就消除，掉落後還能連鎖。無效交換不扣步。<br>③ 在步數內完成本關的收集或分數目標，並清完所有障礙。<br>❄ 冰層：消除上面的食物即可削除一層。<br>▧ 木箱：消除旁邊的食物，或用道具敲掉。<br>▨ 果醬：消除該格食物即可清除；冰層覆蓋果醬時，先破冰再清果醬。<br>格子角落數字代表剩餘總層數。<br>🔨 敲一格　↔ 清一排　⤨ 重排<br>每關都有免費道具，使用不扣步數。空白處沒有棋格，不能交換或跨越消除；每段直欄獨立補充食物，雙盤互不相通。沒有可走步時會自動免費重排。</p>`);}$('#helpBtn').onclick=help;$('#restartBtn').onclick=()=>{if(busy)return;modal('<h2>重新挑戰這一關？</h2><p>本關步數與道具會重置，已通關紀錄保留。</p><button class="primary" id="yes">重新開始</button>');$('#yes').onclick=()=>start(level);};start(Math.min(100,saved.unlocked));
